-- Conferência: deve bater com o número de itens acima.
SELECT u.nome AS casa, count(*) AS itens, count(DISTINCT l."secao") AS secoes
  FROM "ListaPedidoItem" l JOIN "Unidade" u ON u.id = l."unidadeId"
 WHERE u.nome = '104 Sul' GROUP BY 1;
